import fs from 'node:fs';
const r = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const clip = (s, n) => (s.length > n ? s.slice(0, n) + ` …[${s.length}]` : s);
console.log(`# ${r.scenario} stopped=${r.stopped} requests=${r.usage.requests} in=${r.usage.inputTokens} cached=${r.usage.cachedInputTokens} out=${r.usage.outputTokens}`);
for (const t of r.turns) {
  console.log(`\n== ${t.said === null ? '(file opened)' : 'PERSON: ' + t.said}`);
  if (t.fileReport) console.log('   fileReport: ' + clip(JSON.stringify(t.fileReport), 700));
  for (const c of t.calls) {
    const res = c.result !== undefined ? JSON.stringify(c.result) : c.resultStart ?? '';
    console.log(`   CALL ${c.tool} ${clip(JSON.stringify(c.arguments), 400)} -> ${c.state}${c.changesProject ? ' [changes]' : ''}${c.image ? ' [image]' : ''}${c.error ? ' ERROR ' + JSON.stringify(c.error) : ''}`);
    if (process.argv[3] === 'results') console.log('        ' + clip(res, 900));
  }
  for (const m of t.replies) console.log(`   AGENT (${m.state}${m.error ? ' ' + m.error : ''}): ${m.text}`);
  console.log(`   requests: ${t.requests.map(u => u.inputTokens + '/' + u.cachedInputTokens + '/' + u.outputTokens).join(' ')}`);
}
if (r.refusedCalls.length) console.log('\nREFUSED: ' + JSON.stringify(r.refusedCalls));
const p = r.project, w = p.workspace ?? {};
console.log(`\nEND printer=${p.printerPreset} | filament=${p.filamentPreset} | process=${p.processPreset}`);
console.log('    changedSettings=' + JSON.stringify(p.changedSettings));
console.log('    intent=' + JSON.stringify(w.intent));
console.log('    plan=' + clip(JSON.stringify(w.plan ?? null), 600));
console.log('    slicing=' + JSON.stringify(w.slicing?.plates));
console.log('    confirmedFacts=' + JSON.stringify(w.printer?.confirmedFacts));

// Every refused call of the arms given, grouped by tool, with the arguments the model sent:
//   node refused.mjs <arm dir> [<arm dir> ...]
// And, per run, what each model response contained, in order (SEARCH is a hosted tool search), to tell a
// call made without searching for the tool first from one made after its parameters were loaded:
//   node refused.mjs --responses <arm dir> [<arm dir> ...]
import fs from 'node:fs';
import path from 'node:path';
const responses = process.argv[2] === '--responses';
for (const dir of process.argv.slice(responses ? 3 : 2)) {
  const arm = path.basename(path.dirname(dir)) + '/' + path.basename(dir);
  if (responses) {
    for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.log')).sort()) {
      console.log(`\n${arm} ${file.replace('.log', '')}`);
      for (const line of fs.readFileSync(path.join(dir, file), 'utf8').split('\n').filter(l => l.includes('JUSPRIN LIVE REQUEST')))
        console.log('  ' + line.replace(/.*items=/, '').replace(/reasoning,?/g, '').replace(/openrouter:tool_search/g, 'SEARCH').replace(/function_call:\//g, 'call:').trim().slice(0, 200));
    }
    continue;
  }
  const byTool = {};
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json')).sort()) {
    const r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    for (const c of r.refusedCalls) (byTool[`${c.tool} ${c.code}`] ??= []).push(`${file.replace('.json', '')}: ${c.arguments.slice(0, 300)}`);
  }
  console.log(`\n== ${arm}`);
  for (const [key, list] of Object.entries(byTool)) console.log(`${key} x${list.length}\n  ` + list.join('\n  '));
}

