// For each record in the arm dirs given: per turn, the state and the last non-empty reply, clipped.
//   node last.mjs <chars> <scenario prefix> <arm dir> [<arm dir> ...]
import fs from 'node:fs';
import path from 'node:path';
const [chars, prefix, ...dirs] = process.argv.slice(2);
for (const dir of dirs) {
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json') && f.startsWith(prefix)).sort()) {
    const r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    console.log(`\n#### ${path.basename(dir)} ${file} stopped=${r.stopped}`);
    r.turns.forEach((t, i) => {
      if (t.said === null) return;
      const texts = t.replies.filter(m => m.text && m.text.trim());
      const last = texts[texts.length - 1];
      const states = t.replies.map(m => m.state).filter(s => s !== 'complete');
      const mentions = t.replies.map(m => m.text ?? '').join('\n').split(/\n/).filter(l => /PLA/.test(l) && /(UV|sun|soften|heat|brittle|degrad|outdoor|not suit|poor|isn.t ideal|not ideal)/i.test(l)).slice(0, 3);
      console.log(`-- t${i} calls=[${t.calls.map(c => c.tool).join(',')}] ${states.join(',')}`);
      if (mentions.length) console.log('   PLA LINES: ' + mentions.map(l => l.trim().slice(0, 220)).join(' || '));
      console.log('   LAST: ' + (last ? last.text.trim().replace(/\n+/g, ' / ').slice(-Number(chars)) : '(none)'));
    });
  }
}

