// Two checks for the report: node check.mjs <exp dir>
// 1. How many runs of each arm used the hosted tool search at all (from the logs).
// 2. What the app answered when bare named a PETG preset, and which PETG presets presets_list returned.
import fs from 'node:fs';
import path from 'node:path';
const exp = process.argv[2];
for (const dir of ['shared-control/control', 'prompt-weight/bare', 'prompt-weight/once']) {
  const full = path.join(exp, dir);
  const logs = fs.readdirSync(full).filter(f => f.endsWith('.log'));
  const searched = logs.filter(f => fs.readFileSync(path.join(full, f), 'utf8').split('\n').some(l => l.includes('JUSPRIN LIVE REQUEST') && l.includes('openrouter:tool_search')));
  console.log(`${dir}: ${searched.length} of ${logs.length} runs searched; not: ${logs.filter(f => !searched.includes(f)).map(f => f.replace('.log', '')).join(', ')}`);
}
const show = (file, tool) => {
  const r = JSON.parse(fs.readFileSync(path.join(exp, file), 'utf8'));
  for (const t of r.turns) for (const c of t.calls) if (c.tool === tool) {
    const res = c.result !== undefined ? JSON.stringify(c.result) : (c.resultStart ?? '');
    console.log(`\n${file} ${tool} ${JSON.stringify(c.arguments).slice(0, 200)}\n  -> ${c.state} ${res.slice(0, 700)}`);
  }
};
show('prompt-weight/bare/outdoor-fitting-2.json', 'printer_setup_preview');
show('prompt-weight/bare/outdoor-fitting-1.json', 'presets_list');

